<script lang="ts">
 import{openHudLink}from './hud_links';
 import HudContentBrowser from './HudContentBrowser.svelte';
 import HudModuleSettings from './HudModuleSettings.svelte';
 import UiIcon from './UiIcon.svelte';
 import HudAppearance from './HudAppearance.svelte';
 import CrosshairStudio from './CrosshairStudio.svelte';
 import HudQuickControls from './HudQuickControls.svelte';
 import PluginIcon from './PluginIcon.svelte';
 import {hudMetricState} from './hud_data';
 import type {OverlaySnapshot} from './launcher_extensions';
 import {HUD_PRESETS,setAllPlugins,type HudPreset,HUD_ANCHORS,LAUNCHER_PLUGINS,PLUGIN_CATEGORIES,applyHudPreset,deliveryHelp,type HudProfile,type HudModuleId} from './launcher_plugins';
 let {profile=$bindable(),onchange,onclose,saving=false,message='',fpsStatus='',preview=false,frame=null,onlayout=()=>{}}:{profile:HudProfile;onchange:()=>void;onclose:()=>void;saving?:boolean;message?:string;fpsStatus?:string;preview?:boolean;frame?:OverlaySnapshot|null;onlayout?:()=>void}=$props();
 let linkError=$state('');
 let search=$state(''),category=$state('hud'),selected=$state<HudModuleId>('fps');
 let rows=$derived(LAUNCHER_PLUGINS.filter(p=>(category==='all'||p.category===category)&&(p.name+' '+p.description).toLocaleLowerCase().includes(search.toLocaleLowerCase())));
 let module=$derived(profile.modules.find(m=>m.id===selected)!);
 function preset(kind:HudPreset){profile=applyHudPreset($state.snapshot(profile),kind);onchange();}

 let menuDrag:{pointer:number;startX:number;startY:number;left:number;top:number;width:number;height:number}|null=null;
 function beginMenu(event:PointerEvent){if(event.button!==0)return;event.preventDefault();const handle=event.currentTarget as HTMLElement,rect=handle.closest('.editor')!.getBoundingClientRect();menuDrag={pointer:event.pointerId,startX:event.clientX,startY:event.clientY,left:rect.left,top:rect.top,width:rect.width,height:rect.height};handle.setPointerCapture(event.pointerId);}
 function moveMenu(event:PointerEvent){if(!menuDrag||event.pointerId!==menuDrag.pointer)return;const d=menuDrag,w=window.innerWidth,h=window.innerHeight;const left=Math.max(8,Math.min(w-d.width-8,d.left+event.clientX-d.startX)),top=Math.max(8,Math.min(h-d.height-8,d.top+event.clientY-d.startY));profile.menu_offset_x=(left+d.width/2)/w-.5;profile.menu_offset_y=(top+d.height/2)/h-.5;}
 function endMenu(){if(menuDrag){menuDrag=null;onchange();}}
 function menuKey(event:KeyboardEvent){if(['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(event.key)){event.preventDefault();profile.menu_offset_x=Math.max(-.4,Math.min(.4,profile.menu_offset_x+(event.key==='ArrowLeft'?-.01:event.key==='ArrowRight'?.01:0)));profile.menu_offset_y=Math.max(-.4,Math.min(.4,profile.menu_offset_y+(event.key==='ArrowUp'?-.01:event.key==='ArrowDown'?.01:0)));onchange();}}
</script>
<section class="editor" class:chroma={profile.chroma} style:--hud-accent={profile.accent} style:--hud-text={profile.text_color} style:--hud-bg={profile.background_color} style:--menu-alpha={`${(1-profile.menu_transparency)*100}%`} style:--menu-blur={profile.menu_blur?'14px':'0px'} style:translate={`${profile.menu_offset_x*100}vw ${profile.menu_offset_y*100}vh`} onpointermove={moveMenu} onpointerup={endMenu} onpointercancel={endMenu} aria-label="Editor de HUD dentro del juego">
 <header><div class="brand" role="button" tabindex="0" aria-label="Mover menú con el ratón o las flechas" onpointerdown={beginMenu} onkeydown={menuKey}><img src="/logos/tp-launcher.svg" alt=""/><span><strong>TP LAUNCHER</strong><small>PERSONALIZA TU PARTIDA</small></span></div><button onclick={onlayout}><UiIcon name="sliders" size={15}/>Mover widgets</button><button class="return" onclick={onclose}><UiIcon name="play" size={15}/>{preview?'Volver al perfil':'Volver al juego'}<span>{preview?'Vista previa':'F8 / Shift derecho'}</span></button></header>
 <div class="workspace"><aside><small>TU MENÚ</small>{#each PLUGIN_CATEGORIES as c}<button class:active={category===c.id} onclick={()=>category=c.id}><UiIcon name={c.icon} size={17}/>{c.name}</button>{/each}<button class:active={category==='all'} onclick={()=>category='all'}><UiIcon name="grid" size={17}/>Todos los módulos</button><button class:active={category==='resourcepack'} onclick={()=>category='resourcepack'}><UiIcon name="layers" size={17}/>ResourcePacks</button><button class:active={category==='shader'} onclick={()=>category='shader'}><UiIcon name="sun" size={17}/>Shaders</button><button class:active={category==='controls'} onclick={()=>category='controls'}><UiIcon name="sliders" size={17}/>Control rápido</button><button class:active={category==='crosshair'} onclick={()=>category='crosshair'}><UiIcon name="sliders" size={17}/>Mira e impactos</button><button class:active={category==='appearance'} onclick={()=>category='appearance'}><UiIcon name="sliders" size={17}/>Ajustes y colores del HUD</button><div class="preset"><small>PREAJUSTES</small>{#each HUD_PRESETS as p}<button onclick={()=>preset(p.id)}>{p.name}</button>{/each}</div></aside>
 <main>{#if category==='resourcepack'||category==='shader'}{#key category}<HudContentBrowser kind={category} {frame} {preview}/>{/key}{:else if category==='controls'}<HudQuickControls bind:profile {onchange} {frame} {preview}/>{:else if category==='crosshair'}<CrosshairStudio bind:profile {onchange}/>{:else if category==='appearance'}<HudAppearance bind:profile {onchange}/>{:else}<div class="search"><UiIcon name="search" size={16}/><input bind:value={search} placeholder="Busca un módulo…" aria-label="Buscar módulo"/><span>{rows.length} módulos</span></div><div class="bulk"><button onclick={()=>{setAllPlugins(profile,true);onchange();}}>Activar todos los plugins</button><button onclick={()=>{setAllPlugins(profile,false);onchange();}}>Desactivar todos</button></div><small class="availability-note">Cada módulo indica los datos disponibles. Los mods externos se preparan al próximo inicio compatible.</small><div class="cards">{#each rows as p}{@const state=profile.modules.find(m=>m.id===p.id)!}<article class:selected={selected===p.id}><button class="details" onclick={()=>selected=p.id}><PluginIcon id={p.id} size={27}/><strong>{p.name}</strong><small>{deliveryHelp(p.id)}</small>{#if p.delivery!=='installer'&&!preview}<small class="metric-state" class:ready={hudMetricState(p.id,frame).available}>{hudMetricState(p.id,frame).short}</small>{/if}</button>{#if p.project}<button class="project-credit" onclick={()=>void openHudLink(p.project!).catch(error=>linkError=String(error))}>Proyecto en Modrinth ↗</button>{/if}<button class="toggle" class:on={state.enabled} aria-pressed={state.enabled} onclick={()=>{state.enabled=!state.enabled;if(state.id==='no_fog')profile.fog.enabled=state.enabled;onchange();}}>{p.delivery==='installer'?(state.enabled?'PRÓXIMO INICIO':'SIN PREPARAR'):(state.enabled?'ACTIVADO':'DESACTIVADO')}<span></span></button></article>{/each}</div>{#if !rows.length}<p>No hay módulos con esa búsqueda.</p>{/if}{/if}</main>
 <section class="settings">{#if !preview}<div class="connection"><h3><UiIcon name="link" size={16}/>Conexión del juego</h3><p class:ready={frame?.telemetry?.has_world}>{frame?.telemetry?.source||'Esperando puente local'}</p><dl><dt>FPS</dt><dd>{frame?.game_fps!=null?Math.round(frame.game_fps):hudMetricState('fps',frame).short}</dd><dt>MS</dt><dd>{hudMetricState('ping',frame).available&&frame?.telemetry?.ping!=null?Math.round(frame.telemetry.ping):hudMetricState('ping',frame).short}</dd><dt>Posición</dt><dd>{hudMetricState('coordinates',frame).short}</dd></dl><small>{frame?.message||'Inicia Minecraft desde TP con el HUD activado para conectar sus datos.'}</small></div>{/if}<HudModuleSettings bind:profile {selected} {onchange}/><hr/><label class="check"><input type="checkbox" bind:checked={profile.auto_borderless} onchange={onchange}/>Pantalla completa sin bordes</label><small>Para pantalla exclusiva F11, vuelve primero al modo ventana. Los módulos del juego requieren un adaptador compatible.</small><small>{fpsStatus}</small><div class="save-state" role="status">{message|| (saving?'Guardando…':'Diseño guardado automáticamente')}</div></section></div>
 <footer>{#if linkError}<span role="status">{linkError}</span>{/if}<span>OVERLAY UNIVERSAL · WINDOWS</span><span>Esc para volver · Las optimizaciones se aplican en el siguiente inicio</span></footer>
</section>
<style>
.bulk{display:flex;flex-wrap:wrap;gap:8px;margin-bottom:10px}.bulk button{font-size:11px}.availability-note{display:block;color:#b9a5c7;font-size:10px;line-height:1.7;margin-bottom:15px}

.project-credit{font-size:10px;color:#c69cec;text-align:center;padding:8px}

.editor header,.editor .cards article,.editor .connection{background:color-mix(in srgb,var(--hud-bg,#0b0b0f) var(--menu-alpha,65%),transparent)}

.brand{flex:1;cursor:grab;touch-action:none}.brand:active{cursor:grabbing}.brand:focus-visible{outline:1px solid var(--hud-accent)}.chroma{animation:menu-chroma 8s linear infinite}@keyframes menu-chroma{0%,100%{border-color:#a855f7}33%{border-color:#06b6d4}66%{border-color:#10b981}}

 .connection{padding:12px;border:1px solid #ffffff20;border-radius:5px;background:#09070c}.connection p{font-size:11px;margin:10px 0;color:#c5a8de}.connection dl{display:grid;grid-template-columns:auto 1fr;gap:8px;font-size:10px}.connection dd{margin:0;text-align:right;color:#e7d4f7}.connection dt{color:#9b8ba6}.connection .ready,.metric-state.ready{color:#9ee2b6}.metric-state{color:#d4b48e}
 .editor{box-sizing:border-box;width:min(1180px,calc(100vw - 52px));max-height:calc(100vh - 52px);display:flex;flex-direction:column;color:var(--hud-text,#ece4f5);font:14px 'Segoe UI',sans-serif;background:color-mix(in srgb,var(--hud-bg,#0c0b14) var(--menu-alpha,65%),transparent);border:1px solid color-mix(in srgb,var(--hud-accent,#a855f7) 40%,transparent);box-shadow:0 25px 100px #0008;backdrop-filter:blur(var(--menu-blur,14px));border-radius:9px;overflow:hidden}header{display:flex;justify-content:space-between;align-items:center;gap:18px;padding:18px 23px;border-bottom:1px solid #ffffff12;background:#15101caa}.brand{display:flex;align-items:center;gap:12px}.brand img{height:39px;width:36px}.brand span{display:grid;gap:4px}.brand strong{font-size:14px;letter-spacing:.12em}.brand small{color:#b88ad7;font-size:9px;letter-spacing:.12em}button,input{font:inherit;color:inherit}button{cursor:pointer;border:1px solid #ffffff1b;background:#ffffff04;border-radius:4px;padding:10px;display:flex;align-items:center;gap:9px}button:hover{border-color:#b368eb;background:#a855f712}button:focus-visible,input:focus-visible{outline:2px solid #d99bff;outline-offset:2px}.return{font-size:12px;background:#a855f71c;border-color:#a855f750}.return span{color:#ae94c1;font-size:10px}.workspace{display:grid;grid-template-columns:175px minmax(200px,1fr) 220px;min-height:0;overflow:auto;max-height:calc(100vh - 170px)}aside{padding:20px 12px;border-right:1px solid #ffffff10;background:#09090d20;display:flex;flex-direction:column;gap:7px}aside>small,.preset>small{font-size:9px;letter-spacing:.1em;color:#93839f;padding:0 5px 8px}aside button{font-size:11px;text-align:left}.active{color:#e2b9ff!important;border-color:#b368eb!important;background:#a855f71b!important}.preset{display:grid;gap:6px;margin-top:23px}.preset button{font-size:11px;padding:8px}main{padding:18px;min-width:0;overflow:auto}.search{display:flex;align-items:center;gap:10px;padding:0 11px;background:#0005;border:1px solid #ffffff16;border-radius:4px;margin-bottom:15px}.search input{width:100%;min-width:30px;padding:11px 0;background:none;border:0;font-size:12px}.search>span{white-space:nowrap;font-size:9px;color:#95869e}.cards{display:grid;grid-template-columns:repeat(3,minmax(100px,1fr));gap:11px}.cards article{border:1px solid #ffffff15;border-radius:5px;background:linear-gradient(145deg,#25202caa,#15121bcc);overflow:hidden;display:flex;flex-direction:column}.cards article.selected{border-color:#b368eb}.details{border:0;border-radius:0;padding:17px 10px;display:flex;flex-direction:column;gap:10px;text-align:center;flex:1}.details :global(svg){color:#c498e3}.details strong{font-size:12px;font-weight:600}.details small{font-size:9px;color:#a898b3;line-height:1.5}.toggle{justify-content:center;position:relative;padding:8px;font-size:9px;letter-spacing:.06em;border:0;border-top:1px solid #ffffff0e;border-radius:0;background:#0003}.toggle span{width:5px;height:5px;background:#70637d}.toggle.on{background:#a855f731;color:#e6b7ff}.toggle.on span{background:#db98ff;box-shadow:0 0 6px #b67ce3}.settings{padding:20px 17px;border-left:1px solid #ffffff10;background:#09090d10;display:flex;flex-direction:column;gap:20px}h3{font-size:12px;display:flex;gap:8px;align-items:center;margin:0}.settings label{display:grid;grid-template-columns:1fr auto;gap:10px;font-size:11px;color:#bdabc9}input[type=checkbox]{accent-color:#b86cf5}.settings .check{display:flex;align-items:center;gap:7px}.settings small{font-size:10px;color:#8f819b;line-height:1.7}.save-state{font-size:10px;color:#c8a5e0;line-height:1.6}hr{width:100%;border:0;border-top:1px solid #ffffff12;margin:0}footer{padding:11px 22px;display:flex;justify-content:space-between;gap:14px;border-top:1px solid #ffffff12;font-size:9px;color:#8c7c98;letter-spacing:.03em}@media(max-width:1000px){.workspace{grid-template-columns:145px 1fr}.settings{grid-column:1/-1;border-top:1px solid #ffffff14;display:grid;grid-template-columns:repeat(3,1fr)}.cards{grid-template-columns:repeat(3,1fr)}.settings hr{display:none}}@media(max-width:700px){.workspace{grid-template-columns:110px 1fr}.cards{grid-template-columns:repeat(2,1fr)}.settings{grid-template-columns:1fr 1fr}.editor{width:calc(100vw - 16px);max-height:calc(100vh - 16px)}.return span,footer>span:last-child{display:none}header{padding:12px}.details{padding:12px 7px}}
</style>
